function buildLandingPageHTML() {
    return "<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>كوين إم دي ريد</title>\n  <style>\n    :root {\n      --bg:#090909;\n      --card:#151010;\n      --card2:#1a1313;\n      --line:rgba(255,255,255,.08);\n      --red:#ff1f1f;\n      --red2:#b10d0d;\n      --gold:#d4af37;\n      --green:#18c964;\n      --blue:#2f7bf6;\n      --yellow:#c89a11;\n      --text:#fff7f7;\n      --muted:#c7b9b9;\n      --shadow:0 12px 28px rgba(0,0,0,.35);\n    }\n    *{box-sizing:border-box}\n    body{\n      margin:0;\n      font-family:Tahoma,Arial,sans-serif;\n      background:radial-gradient(circle at top,#2b0707 0%,#120404 35%,#080808 100%);\n      color:var(--text);\n      min-height:100vh;\n      overflow-x:hidden;\n    }\n    body::before{\n      content:\"\";\n      position:fixed;\n      inset:0;\n      background-image:\n        radial-gradient(circle at 20% 20%, rgba(255,255,255,.18) 0 1px, transparent 1px),\n        radial-gradient(circle at 80% 40%, rgba(255,255,255,.16) 0 1.2px, transparent 1.2px),\n        radial-gradient(circle at 40% 80%, rgba(255,255,255,.12) 0 1px, transparent 1px),\n        radial-gradient(circle at 70% 10%, rgba(255,255,255,.1) 0 1px, transparent 1px);\n      background-size:160px 160px, 210px 210px, 240px 240px, 300px 300px;\n      animation:snow 18s linear infinite;\n      pointer-events:none;\n      opacity:.65;\n    }\n    @keyframes snow{from{transform:translateY(-30px)}to{transform:translateY(30px)}}\n    a{text-decoration:none;color:inherit}\n    .wrap{max-width:960px;margin:0 auto;padding:16px}\n    .topbar{\n      display:flex;align-items:center;justify-content:space-between;\n      padding:14px 16px;margin-top:8px;border-radius:18px;\n      background:rgba(20,7,7,.78);border:1px solid var(--line);box-shadow:var(--shadow)\n    }\n    .brand{font-size:28px;font-weight:700;letter-spacing:.3px}\n    .brand .red{color:#d61616}\n    .menu-btn{\n      width:54px;height:54px;border-radius:16px;border:1px solid rgba(255,72,72,.2);\n      background:linear-gradient(180deg,#341111,#230b0b);display:grid;place-items:center;box-shadow:var(--shadow)\n    }\n    .menu-lines,.menu-lines::before,.menu-lines::after{content:\"\";display:block;width:22px;height:3px;border-radius:99px;background:#e14a4a;position:relative}\n    .menu-lines::before{position:absolute;top:-7px}\n    .menu-lines::after{position:absolute;top:7px}\n    .hero{\n      text-align:center;padding:48px 18px 28px;\n    }\n    .hero h1{font-size:52px;line-height:1.25;margin:0 0 14px;font-weight:800}\n    .hero h1 .gold{color:var(--gold)}\n    .hero p{font-size:23px;line-height:1.8;color:#f1e6e6;max-width:760px;margin:0 auto}\n    .buttons{display:grid;gap:16px;max-width:520px;margin:28px auto 0}\n    .cta,.panel-btn{\n      display:flex;align-items:center;justify-content:center;gap:10px;\n      min-height:74px;border-radius:18px;font-size:31px;font-weight:700;\n      border:1px solid rgba(255,255,255,.06);box-shadow:var(--shadow);cursor:pointer;transition:.18s transform,.18s opacity\n    }\n    .cta:hover,.panel-btn:hover,.mini-btn:hover,.action-btn:hover{transform:translateY(-2px)}\n    .cta{background:linear-gradient(180deg,#ff0808,#d10000)}\n    .panel-btn{background:#201313;color:#f4eded}\n    .save-card{background:#102214;color:#49dc79}\n    .reply-card{background:#0d1b38;color:#3f8cff}\n    .points-card{background:#31250a;color:#ffd45a}\n    .section{\n      background:rgba(16,9,9,.88);border:1px solid var(--line);border-radius:24px;padding:22px;margin-top:20px;box-shadow:var(--shadow)\n    }\n    .section h2{margin:0 0 10px;font-size:28px}\n    .section p{margin:0;color:var(--muted);line-height:1.9;font-size:17px}\n    .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin-top:16px}\n    .stat{background:var(--card2);border:1px solid var(--line);border-radius:18px;padding:16px}\n    .stat .label{color:var(--muted);font-size:14px;margin-bottom:8px}\n    .stat .value{font-size:28px;font-weight:700}\n    .login{\n      display:grid;grid-template-columns:1fr 1fr auto;gap:12px;margin-top:18px\n    }\n    input{\n      width:100%;background:#0d0a0a;border:1px solid rgba(255,255,255,.08);color:#fff;border-radius:16px;\n      padding:16px;font-size:16px;outline:none\n    }\n    input:focus{border-color:rgba(255,70,70,.45)}\n    .action-btn,.mini-btn{\n      border:none;border-radius:16px;padding:16px 18px;font-size:16px;font-weight:700;cursor:pointer;color:#fff\n    }\n    .action-btn{background:linear-gradient(180deg,#ff1717,#d30a0a)}\n    .mini-btn{background:#251919}\n    .links{display:flex;flex-wrap:wrap;gap:10px;margin-top:14px}\n    .chip{padding:12px 14px;border-radius:999px;background:#1f1414;border:1px solid var(--line);font-size:14px}\n    .toggle-row{\n      margin-top:18px;background:#161010;border:1px solid var(--line);border-radius:18px;padding:16px;\n      display:flex;align-items:center;justify-content:space-between;gap:16px\n    }\n    .switch{position:relative;width:64px;height:34px;display:inline-block}\n    .switch input{display:none}\n    .slider{position:absolute;inset:0;background:#463636;border-radius:99px;transition:.2s}\n    .slider:before{content:\"\";position:absolute;width:26px;height:26px;right:4px;top:4px;background:#fff;border-radius:50%;transition:.2s}\n    .switch input:checked + .slider{background:#1daa57}\n    .switch input:checked + .slider:before{transform:translateX(-30px)}\n    .steps{margin-top:14px;display:grid;gap:10px}\n    .step{background:#150f0f;border:1px solid var(--line);padding:14px 16px;border-radius:16px;line-height:1.8}\n    .emoji-box{margin-top:14px;background:#160f0f;border:1px dashed rgba(255,255,255,.16);padding:14px 16px;border-radius:18px;font-size:28px;line-height:1.8;word-break:break-word}\n    .notice{margin-top:14px;padding:14px 16px;border-radius:16px;background:rgba(255,209,102,.1);border:1px solid rgba(255,209,102,.16);color:#ffe29a;line-height:1.8}\n    .ok{color:#54dc82}.muted{color:var(--muted)}\n    .hidden{display:none !important}\n    .divider{height:1px;background:rgba(255,255,255,.08);margin:18px 0}\n    .footer{padding:30px 0 10px;text-align:center;color:#9f8f8f;font-size:14px}\n    @media (max-width:720px){\n      .hero h1{font-size:40px}\n      .hero p{font-size:20px}\n      .cta,.panel-btn{font-size:24px;min-height:64px}\n      .login{grid-template-columns:1fr}\n      .topbar{padding:12px}\n      .brand{font-size:24px}\n    }\n  </style>\n</head>\n<body>\n  <div class=\"wrap\">\n    <div class=\"topbar\">\n      <div class=\"brand\">كوين إم دي <span class=\"red\">ريد</span></div>\n      <div class=\"menu-btn\"><span class=\"menu-lines\"></span></div>\n    </div>\n\n    <section class=\"hero\">\n      <h1>الصغير<span class=\"gold\">الروبوت</span> إصدار</h1>\n      <p>أتمتة واتساب سريعة وآمنة ومبسطة. استمتع بأفضل الميزات بأقل قدر من الإعدادات.</p>\n      <div class=\"buttons\">\n        <a class=\"cta\" id=\"publishNowBtn\" href=\"/pair\">🔗 انشر الآن</a>\n        <a class=\"panel-btn\" href=\"/settings\">⚙️ إعدادات</a>\n        <a class=\"panel-btn save-card\" id=\"autoSaveBtn\" href=\"/auto-save\">💾 الحفظ التلقائي</a>\n        <a class=\"panel-btn points-card\" id=\"pointsBtn\" href=\"/points\">🪙 نقاطي</a>\n      </div>\n    </section>\n\n    <section class=\"section\" id=\"loginSection\">\n      <h2>تسجيل الدخول للرقم المربوط</h2>\n      <p>اكتب الرقم المربوط وكلمة سر لوحة الإعدادات لعرض معلوماتك وتفعيل الحفظ التلقائي ومتابعة أوامر النشر.</p>\n      <div class=\"login\">\n        <input id=\"phoneInput\" placeholder=\"الرقم المربوط\" inputmode=\"numeric\" />\n        <input id=\"passInput\" placeholder=\"كلمة السر\" />\n        <button class=\"action-btn\" id=\"loginBtn\">دخول</button>\n      </div>\n      <div class=\"links\">\n        <span class=\"chip\">رابط اللوحة: /settings</span>\n        <span class=\"chip\">أمر الإعجابات: .GNA</span>\n        <span class=\"chip\">الأمر يُستخدم من واتساب الرقم المربوط</span>\n      </div>\n      <div class=\"notice hidden\" id=\"loginMessage\"></div>\n    </section>\n\n    <section class=\"section hidden\" id=\"dashboardSection\">\n      <h2>لوحة التحكم السريعة</h2>\n      <p id=\"welcomeText\">تم تسجيل الدخول بنجاح.</p>\n      <div class=\"grid\">\n        <div class=\"stat\"><div class=\"label\">الرقم النشط</div><div class=\"value\" id=\"phoneValue\">—</div></div>\n        <div class=\"stat\"><div class=\"label\">نقاطي</div><div class=\"value\" id=\"pointsValue\">0</div></div>\n        <div class=\"stat\"><div class=\"label\">أرقامي المربوطة</div><div class=\"value\" id=\"linkedValue\">0</div></div>\n        <div class=\"stat\"><div class=\"label\">الجلسات النشطة</div><div class=\"value\" id=\"activeValue\">0</div></div>\n      </div>\n\n      <div class=\"toggle-row\" id=\"autoSaveSection\">\n        <div>\n          <div style=\"font-size:18px;font-weight:700\">الحفظ التلقائي</div>\n          <div class=\"muted\" style=\"margin-top:6px\">عند تفعيله يتم حفظ إعدادات الرقم مباشرة داخل النظام.</div>\n        </div>\n        <label class=\"switch\">\n          <input type=\"checkbox\" id=\"autoSaveToggle\" />\n          <span class=\"slider\"></span>\n        </label>\n      </div>\n\n      <div class=\"divider\"></div>\n\n      <div id=\"publishBlock\">\n        <h2 style=\"margin-bottom:8px\">قسم النشر الآن</h2>\n        <p>من داخل محادثتك الخاصة للرقم المربوط على واتساب استخدم الأمر التالي ثم أكمل الخطوات حسب الرسائل التي يرسلها لك النظام.</p>\n        <div class=\"emoji-box\" id=\"commandBox\">.GNA</div>\n        <div class=\"steps\">\n          <div class=\"step\">1) أرسل <b>.GNA</b> في محادثتك الخاصة للرقم المربوط.</div>\n          <div class=\"step\">2) أرسل رابط منشور القناة بصيغة واتساب.</div>\n          <div class=\"step\">3) أرسل عدد الإعجابات المطلوب بالأرقام فقط.</div>\n          <div class=\"step\">4) أرسل شكل أو أكثر من أشكال الإعجاب المتاحة ليتم التوزيع عليها.</div>\n        </div>\n        <div class=\"emoji-box\" id=\"emojiChoices\">💤 💭 💜 🇾🇪 👇 ⚠️ 🔄 😅 👈 😀 😁 💚</div>\n        <div class=\"notice\" id=\"publishNote\">ملحوظة: العدد الفعلي يعتمد على عدد الجلسات النشطة المربوطة لنفس الحساب. إذا كان عندك رقم واحد نشط فسيتم تنفيذ إعجاب واحد فعلياً لذلك المنشور.</div>\n      </div>\n\n      <div class=\"divider\"></div>\n\n      <div id=\"pointsBlock\">\n        <h2 style=\"margin-bottom:8px\">قسم نقاطي</h2>\n        <p>كل تنفيذ ناجح للإعجابات يضيف نقاطاً إلى حسابك بحسب عدد الإعجابات الفعلية التي تم تنفيذها من الجلسات النشطة.</p>\n        <div class=\"grid\">\n          <div class=\"stat\"><div class=\"label\">إجمالي النقاط</div><div class=\"value\" id=\"pointsValue2\">0</div></div>\n          <div class=\"stat\"><div class=\"label\">سعة اللايكات من النقاط</div><div class=\"value\" id=\"capacityValue\">0</div></div>\n        </div>\n        <div class=\"links\">\n          <button class=\"mini-btn\" id=\"dailyGiftBtn\">🎁 هدية يومية +100</button>\n          <span class=\"chip\">كل 30 نقطة = 500 لايك</span>\n          <span class=\"chip\" id=\"giftStatusChip\">الهدية اليومية متاحة</span>\n        </div>\n        <div class=\"links\" id=\"connectedPhones\"></div>\n      </div>\n    </section>\n\n    <div class=\"footer\">واجهة سريعة مضافة لموقع الربط مع قسم إعدادات وقسم نشر الآن والحفظ التلقائي وقسم نقاطي.</div>\n  </div>\n\n  <script>\n    const state = { phone: '', pass: '', app: 'default', settings: null, stats: null };\n    const loginMessage = document.getElementById('loginMessage');\n    const dashboardSection = document.getElementById('dashboardSection');\n    const phoneInput = document.getElementById('phoneInput');\n    const passInput = document.getElementById('passInput');\n    const loginBtn = document.getElementById('loginBtn');\n    const publishNowBtn = document.getElementById('publishNowBtn');\n    const autoSaveBtn = document.getElementById('autoSaveBtn');\n    const pointsBtn = document.getElementById('pointsBtn');\n    const autoSaveToggle = document.getElementById('autoSaveToggle');\n    const dailyGiftBtn = document.getElementById('dailyGiftBtn');\n\n    function showMessage(text, ok) {\n      loginMessage.textContent = text;\n      loginMessage.classList.remove('hidden');\n      loginMessage.style.background = ok ? 'rgba(76,217,100,.12)' : 'rgba(255,75,75,.12)';\n      loginMessage.style.border = ok ? '1px solid rgba(76,217,100,.22)' : '1px solid rgba(255,75,75,.22)';\n      loginMessage.style.color = ok ? '#76f59b' : '#ff9f9f';\n    }\n\n    function scrollToEl(id) {\n      const el = document.getElementById(id);\n      if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });\n    }\n\n    function requireLogin(targetId) {\n      if (!state.phone) {\n        showMessage('سجل دخولك أولاً بالرقم المربوط وكلمة السر.', false);\n        scrollToEl('loginSection');\n        return false;\n      }\n      if (targetId) scrollToEl(targetId);\n      return true;\n    }\n\n    async function loadDashboard() {\n      const res = await fetch('/api/dashboard/load?num=' + encodeURIComponent(state.phone) + '&app=' + encodeURIComponent(state.app));\n      const data = await res.json();\n      if (!data.success) throw new Error(data.error || 'تعذر تحميل البيانات');\n      state.settings = data.settings || {};\n      state.stats = data.stats || {};\n      document.getElementById('welcomeText').textContent = 'مرحباً بك، هذا ملخص رقمك المربوط وإعدادات النشر السريع.';\n      document.getElementById('phoneValue').textContent = data.phone || state.phone;\n      document.getElementById('pointsValue').textContent = String(state.stats.points || 0);\n      document.getElementById('pointsValue2').textContent = String(state.stats.points || 0);\n      document.getElementById('linkedValue').textContent = String(state.stats.linkedNumbers || 0);\n      document.getElementById('activeValue').textContent = String(state.stats.activeSessions || 0);\n      document.getElementById('capacityValue').textContent = String(state.stats.pointLikeCapacity || 0);\n      const giftChip = document.getElementById('giftStatusChip');\n      if (giftChip) {\n        giftChip.textContent = state.stats.lastDailyGiftAt ? 'آخر هدية: ' + new Date(state.stats.lastDailyGiftAt).toLocaleString('ar-EG') : 'الهدية اليومية متاحة';\n      }\n      autoSaveToggle.checked = (state.settings.autoSave || 'on') === 'on';\n      document.getElementById('emojiChoices').textContent = (data.gna && data.gna.emojiChoices ? data.gna.emojiChoices.join(' ') : '💤 💭 💜 🇾🇪 👇 ⚠️ 🔄 😅 👈 😀 😁 💚');\n      document.getElementById('commandBox').textContent = (data.gna && data.gna.command) || '.GNA';\n      if (data.gna && data.gna.note) document.getElementById('publishNote').textContent = data.gna.note;\n      const chips = document.getElementById('connectedPhones');\n      chips.innerHTML = '';\n      const phones = Array.isArray(state.stats.connectedNumbers) ? state.stats.connectedNumbers : [];\n      if (!phones.length) {\n        chips.innerHTML = '<span class=\"chip\">لا يوجد أرقام نشطة حالياً</span>';\n      } else {\n        phones.forEach(function(phone) {\n          const span = document.createElement('span');\n          span.className = 'chip';\n          span.textContent = phone;\n          chips.appendChild(span);\n        });\n      }\n      dashboardSection.classList.remove('hidden');\n    }\n\n    async function doLogin() {\n      try {\n        loginBtn.disabled = true;\n        loginBtn.textContent = 'جاري الدخول...';\n        const num = (phoneInput.value || '').replace(/\\D/g, '');\n        const pass = (passInput.value || '').trim();\n        if (!num || !pass) {\n          showMessage('اكتب الرقم وكلمة السر أولاً.', false);\n          return;\n        }\n        const res = await fetch('/api/login', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ num: num, pass: pass })\n        });\n        const data = await res.json();\n        if (!data.success) throw new Error(data.error || data.message || 'فشل تسجيل الدخول');\n        state.phone = data.number || num;\n        state.pass = pass;\n        state.app = data.app || 'default';\n        await loadDashboard();\n        showMessage('تم تسجيل الدخول بنجاح.', true);\n        scrollToEl('dashboardSection');\n      } catch (error) {\n        showMessage(error.message || 'فشل تسجيل الدخول', false);\n      } finally {\n        loginBtn.disabled = false;\n        loginBtn.textContent = 'دخول';\n      }\n    }\n\n    async function saveAutoSave() {\n      if (!requireLogin('autoSaveSection')) return;\n      if (!state.settings) return;\n      try {\n        const next = Object.assign({}, state.settings, {\n          num: state.phone,\n          app: state.app,\n          autoSave: autoSaveToggle.checked ? 'on' : 'off'\n        });\n        const res = await fetch('/api/settings/save', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify(next)\n        });\n        const data = await res.json();\n        if (!data.success) throw new Error(data.error || 'تعذر حفظ الحالة');\n        state.settings = data.settings || state.settings;\n        showMessage('تم تحديث الحفظ التلقائي بنجاح.', true);\n      } catch (error) {\n        autoSaveToggle.checked = !autoSaveToggle.checked;\n        showMessage(error.message || 'فشل حفظ الحفظ التلقائي', false);\n      }\n    }\n\n    async function claimDailyGift() {\n      if (!requireLogin('pointsBlock')) return;\n      try {\n        if (dailyGiftBtn) { dailyGiftBtn.disabled = true; dailyGiftBtn.textContent = 'جاري الاستلام...'; }\n        const res = await fetch('/api/daily-gift', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ num: state.phone, pass: state.pass })\n        });\n        const data = await res.json();\n        if (!data.success) throw new Error(data.error || 'تعذر استلام الهدية');\n        document.getElementById('pointsValue').textContent = String(data.points || 0);\n        document.getElementById('pointsValue2').textContent = String(data.points || 0);\n        document.getElementById('capacityValue').textContent = String(Math.floor((Number(data.points||0)/30)) * 500);\n        const giftChip = document.getElementById('giftStatusChip');\n        if (giftChip) giftChip.textContent = 'تم استلام الهدية اليومية بنجاح';\n        showMessage('تمت إضافة 100 نقطة إلى حسابك.', true);\n      } catch (error) {\n        showMessage(error.message || 'فشل استلام الهدية اليومية', false);\n      } finally {\n        if (dailyGiftBtn) { dailyGiftBtn.disabled = false; dailyGiftBtn.textContent = '🎁 هدية يومية +100'; }\n      }\n    }\n\n    loginBtn.addEventListener('click', doLogin);\n    passInput.addEventListener('keydown', function(e){ if (e.key === 'Enter') doLogin(); });\n    phoneInput.addEventListener('keydown', function(e){ if (e.key === 'Enter') doLogin(); });\n    publishNowBtn.addEventListener('click', function(){ if (state.phone) scrollToEl('publishBlock'); else scrollToEl('loginSection'); });\n    autoSaveBtn.addEventListener('click', function(){ if (requireLogin('autoSaveSection')) autoSaveToggle.focus(); });\n    pointsBtn.addEventListener('click', function(){ requireLogin('pointsBlock'); });\n    autoSaveToggle.addEventListener('change', saveAutoSave);\n    if (dailyGiftBtn) dailyGiftBtn.addEventListener('click', claimDailyGift);\n  </script>\n</body>\n</html>";
}

function buildLandingSectionHTML(sectionId = '') {
    const safeId = JSON.stringify(String(sectionId || ''));
    return buildLandingPageHTML().replace('</body>', `<script>window.__OPEN_SECTION__=${safeId};window.addEventListener('DOMContentLoaded',()=>{const target=window.__OPEN_SECTION__;if(target){setTimeout(()=>{document.getElementById(target)?.scrollIntoView({behavior:'smooth',block:'start'});},120);}});</script></body>`);
}

function buildPairPageHTML() {
    return `<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8" /><meta name="viewport" content="width=device-width,initial-scale=1.0" /><title>ربط الرقم</title><style>body{margin:0;font-family:Tahoma,Arial,sans-serif;background:#090909;color:#fff} .wrap{max-width:760px;margin:auto;padding:20px} .card{background:#161010;border:1px solid rgba(255,255,255,.08);border-radius:24px;padding:24px;margin-top:24px} input,button{width:100%;padding:16px;border-radius:16px;border:1px solid rgba(255,255,255,.08);background:#0f0b0b;color:#fff;font-size:16px;box-sizing:border-box} button{background:#d30a0a;cursor:pointer;font-weight:700;margin-top:12px} .code{margin-top:16px;padding:18px;border-radius:18px;background:#1b1414;font-size:30px;text-align:center;letter-spacing:2px} a{color:#ffcd66;text-decoration:none}</style></head><body><div class="wrap"><div class="card"><h1 style="margin-top:0">ربط رقمك من الموقع</h1><p>اكتب رقم واتساب مع مفتاح الدولة. سيتم إنشاء كود ربط مباشر من الموقع.</p><input id="phone" placeholder="مثال 967771234567" inputmode="numeric" /><button id="go">إنشاء كود الربط</button><div id="msg" style="margin-top:12px;color:#e7d7d7"></div><div id="code" class="code" style="display:none"></div><p style="margin-top:18px;color:#c9b9b9">بعد الربط افتح <a href="/settings">الإعدادات</a> أو <a href="/points">نقاطي</a>.</p></div></div><script>const msg=document.getElementById('msg');const code=document.getElementById('code');document.getElementById('go').onclick=async()=>{const phone=(document.getElementById('phone').value||'').replace(/\D/g,'');if(!phone){msg.textContent='اكتب الرقم أولاً';return;}msg.textContent='جاري إنشاء كود الربط...';code.style.display='none';try{const res=await fetch('/api/pair',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({phone})});const data=await res.json();if(!data.success) throw new Error(data.error||'فشل إنشاء الكود');msg.textContent='تم إنشاء الكود، استخدمه من واتساب > الأجهزة المرتبطة > ربط جهاز';code.style.display='block';code.textContent=data.code||'—';}catch(err){msg.textContent=err.message||'فشل إنشاء الكود';}};</script></body></html>`;
}

